# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">CÜMLENİN ÖGELERİ UYGULAMASI VE CÜMLEDE VURGU KURALLARI</text>\n  <rect x="20" y="48" width="320" height="192" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Öge Bulma Sırası (Y - Ö - N Yöntemi)</text>\n  <text x="34" y="96" font-size="11" fill="#334155">1. <tspan font-weight="bold" fill="#1e3a8a">Yüklem:</tspan> Cümlenin yargı bildiren temel ögesidir.</text>\n  <text x="34" y="118" font-size="11" fill="#334155">2. <tspan font-weight="bold" fill="#1e3a8a">Özne:</tspan> Yükleme sorulan <tspan font-weight="bold">"Kim / Ne?"</tspan> sorusu.</text>\n  <text x="34" y="140" font-size="11" fill="#334155">3. <tspan font-weight="bold" fill="#1e3a8a">Nesne:</tspan> Belirtisiz ("Ne?"), Belirtili ("Neyi, Kimi?").</text>\n  <text x="34" y="162" font-size="11" fill="#334155">4. <tspan font-weight="bold" fill="#1e3a8a">Yer Tamlayıcısı:</tspan> "-e, -de, -den" hal ekli sorular.</text>\n  <text x="34" y="184" font-size="11" fill="#334155">5. <tspan font-weight="bold" fill="#1e3a8a">Zarf Tamlayıcısı:</tspan> "Ne zaman, Nasıl, Niçin?"</text>\n  <text x="34" y="212" font-size="10.5" font-weight="bold" fill="#b91c1c">Altın Kural: Tamlamalar ve deyimler asla bölünmez!</text>\n  <rect x="355" y="48" width="325" height="192" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Cümlede Vurgunun Yeri</text>\n  <text x="370" y="98" font-size="11" fill="#334155">• <tspan font-weight="bold" fill="#14532d">Fiil cümlelerinde:</tspan> Yüklemden <tspan font-weight="bold">hemen önceki</tspan> ögededir.</text>\n  <text x="378" y="114" font-size="10.5" fill="#475569">(Fiil yüklem cümlenin en başındaysa vurgu yüklemdedir.)</text>\n  <text x="370" y="138" font-size="11" fill="#334155">• <tspan font-weight="bold" fill="#14532d">İsim cümlelerinde:</tspan> Vurgu daima <tspan font-weight="bold">yüklemin kendisindedir.</tspan></text>\n  <text x="370" y="162" font-size="11" fill="#334155">• <tspan font-weight="bold" fill="#14532d">\'mi\' ve \'de/da\' varsa:</tspan> Kendinden önceki ögededir.</text>\n  <text x="370" y="186" font-size="11" fill="#334155">• <tspan font-weight="bold" fill="#14532d">Soru sözcüğü varsa:</tspan> Soru sözcüğünün üzerindedir.</text>\n  <text x="370" y="214" font-size="10.5" font-weight="bold" fill="#15803d">Örn: Atatürk öğretmenlere [Kongre\'de] seslendi. (Yer T.)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ARA SÖZ / ARA CÜMLE VE CÜMLE DIŞI UNSURLAR</text>\n  <rect x="25" y="48" width="315" height="192" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">1. Bir Ögenin Açıklayıcısı Olan Ara Söz</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• İki virgül <tspan font-weight="bold">( , ... , )</tspan> veya iki kısa çizgi <tspan font-weight="bold">( - ... - )</tspan></text>\n  <text x="48" y="114" font-size="11" fill="#334155">arasında yazılarak kendinden önceki ögeyi açıklar.</text>\n  <text x="40" y="140" font-size="11" font-weight="bold" fill="#854d0e">Örnek 1 (Öznenin Açıklayıcısı):</text>\n  <text x="45" y="158" font-size="10.5" fill="#334155">"Atatürk, <tspan font-weight="bold" fill="#b91c1c">Başöğretmenimiz</tspan>, eğitime öncülük etti."</text>\n  <text x="40" y="184" font-size="11" font-weight="bold" fill="#854d0e">Örnek 2 (Yer Tamlayıcısının Açıklayıcısı):</text>\n  <text x="45" y="202" font-size="10.5" fill="#334155">"Ankara\'ya, <tspan font-weight="bold" fill="#b91c1c">başkentimize</tspan>, dün akşam ulaştık."</text>\n  <text x="40" y="224" font-size="10.5" fill="#475569">→ Açıkladığı ögenin bir parçası kabul edilir.</text>\n  <rect x="360" y="48" width="315" height="192" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">2. Ara Cümle ve Cümle Dışı Unsurlar</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• Herhangi bir ögeyi açıklamayan, konuşmacının</text>\n  <text x="383" y="114" font-size="11" fill="#334155">duygusunu/yorumunu bildiren ara cümleler</text>\n  <text x="383" y="130" font-size="11" font-weight="bold" fill="#9d174d">cümle dışı unsur (CDU)</text>\n  <text x="375" y="154" font-size="10.5" fill="#334155">Örn: "Bu eseri - <tspan font-weight="bold" fill="#be185d">eminim sen de seversin</tspan> - yeni aldım."</text>\n  <text x="375" y="180" font-size="11" font-weight="bold" fill="#831843">Diğer Cümle Dışı Unsurlar:</text>\n  <text x="380" y="198" font-size="10.5" fill="#334155">• Hitaplar ("Gençler!", "Sevgili Öğretmenim,")</text>\n  <text x="380" y="214" font-size="10.5" fill="#334155">• Ünlemler ("Eyvah!") ve Bağlaçlar ("ancak, çünkü")</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ATATÜRK VE EĞİTİM METNİ, İŞLEM BASAMAKLARI VE YAZIM KURALLARI</text>\n  <rect x="25" y="48" width="315" height="192" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Atatürk\'ün Eğitime Bakışı (Metin Analizi)</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Kütahya-Eskişehir Savaşları sürerken (Temmuz</text>\n  <text x="48" y="115" font-size="11" fill="#334155">1921) Ankara\'da <tspan font-weight="bold">Maarif Kongresi\'ni</tspan> toplamıştır.</text>\n  <text x="40" y="140" font-size="11" fill="#334155">• "Cehaletle savaş, düşmanla savaştan daha az</text>\n  <text x="48" y="157" font-size="11" fill="#334155">önemli değildir" anlayışını benimsemiştir.</text>\n  <text x="40" y="182" font-size="11" font-weight="bold" fill="#1e3a8a">• "Öğretmenler! Yeni nesil sizin eseriniz olacaktır."</text>\n  <text x="40" y="206" font-size="11" fill="#334155">• 24 Kasım 1928\'de <tspan font-weight="bold">Başöğretmen</tspan> unvanını almıştır.</text>\n  <rect x="360" y="48" width="315" height="192" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Yazım, Noktalama ve İşlem Basamakları</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• <tspan font-weight="bold">Belirli Günler:</tspan> "10 Kasım Atatürk\'ü Anma Günü",</text>\n  <text x="383" y="114" font-size="11" fill="#334155">"24 Kasım Öğretmenler Günü" büyük harfle yazılır.</text>\n  <text x="375" y="138" font-size="11" fill="#334155">• <tspan font-weight="bold">Ara Söz Noktalaması:</tspan> Başında ve sonunda</text>\n  <text x="383" y="154" font-size="11" fill="#334155">eşleştirilmiş iki virgül veya iki kısa çizgi kullanılır.</text>\n  <text x="375" y="178" font-size="11" fill="#334155">• <tspan font-weight="bold">İşlem Basamaklarına Göre Yazma (T.8.4.6):</tspan></text>\n  <text x="383" y="194" font-size="10.5" fill="#334155">Bir işin yapılışı kronolojik ve mantıksal sırayla</text>\n  <text x="383" y="210" font-size="10.5" fill="#334155">(ilk olarak, ardından, daha sonra, son olarak) yazılır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
